describe('Success Feedback After Valid Form Submission', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should display success feedback after valid form submission', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/form/submit').as('formSubmit');

    // Fill in the form with valid data
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a test message');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API response
    cy.wait('@formSubmit');

    // Verify success feedback is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');

    // Verify success icon appears
    cy.get('[data-testid="success-icon"]').should('be.visible');

    // Verify form is cleared for next submission
    cy.get('[data-testid="name-input"]').should('have.value', '');
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="message-textarea"]').should('have.value', '');
  });

  it('should display error feedback when form submission fails', () => {
    // Intercept the form submission API with a failure response
    cy.intercept('POST', '/api/form/submit', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('formSubmitError');

    // Fill in the form with valid data
    cy.get('[data-testid="name-input"]').type('Jane Smith');
    cy.get('[data-testid="email-input"]').type('jane.smith@example.com');
    cy.get('[data-testid="message-textarea"]').type('Please review my request');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API response
    cy.wait('@formSubmitError');

    // Verify error feedback is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Form submission failed');

    // Verify error icon appears
    cy.get('[data-testid="error-icon"]').should('be.visible');

    // Verify success icon is not visible
    cy.get('[data-testid="success-icon"]').should('not.exist');

    // Verify form is still filled with data
    cy.get('[data-testid="name-input"]').should('have.value', 'Jane Smith');
    cy.get('[data-testid="email-input"]').should('have.value', 'jane.smith@example.com');
    cy.get('[data-testid="message-textarea"]').should('have.value', 'Please review my request');
  });
});
